style.css:
@-moz-document domain("open.spotify.com") {
/* =====================================================
       SILVERKING — NEON BLUE / BLACK / SILVER
       ===================================================== */


    /* =========================
       TOP NAVIGATION
       ========================= */

    .Root__nav-bar {
        background:
            linear-gradient(
                #000000d9,
                #020b18e6
            ) !important;

        border: none !important;

        box-shadow:
            0 2px 15px #008cff20 !important;
    }


    /* =========================
       LEFT SIDEBAR
       ========================= */

    ._465f483e874c2ff4e7b473eae411a39b-scss {

        background:
            linear-gradient(
                #000000cc,
                #020914e6
            ),
            url(https://www.image2url.com/r2/default/images/1788350372875-3ab4087f-9b76-488a-8e51-783d3f4f984f.jpeg) !important;

        background-size: cover !important;
        background-position: center !important;
        background-attachment: fixed !important;

        border: none !important;

        box-shadow:
            inset -1px 0 0 #00bfff25 !important;
    }


    /* =========================
       SIDEBAR INNER AREA
       ========================= */

    ._469c4cc13afd48634cc3c8cb1e07205c-scss {

        background:
            linear-gradient(
                #000000cc,
                #020b18e6
            ) !important;

        border: none !important;
    }


    /* =========================
       NOW PLAYING BAR
       ========================= */

    .now-playing-bar-container {

        border: none !important;

        background:
            linear-gradient(
                #020e1ce6,
                #000000f2
            ) !important;

        box-shadow:
            0 -2px 20px #00aaff18 !important;
    }


    /* =========================
       PLAYBACK TIME
       ========================= */

    .playback-bar__progress-time {

        color:
            #e8f3ff !important;

        text-shadow:
            0 0 5px #00bfff55 !important;
    }


    /* =========================
       PROGRESS BAR
       ========================= */

    .progress-bar--is-active {

        background:
            #071522 !important;
    }


    .progress-bar {

        background:
            #18232e !important;
    }


    /* Progress bar hover */

    .progress-bar:hover {

        background:
            #203442 !important;
    }


    /* Progress fill */

    .progress-bar__fg {

        background:
            #00bfff !important;

        box-shadow:
            0 0 8px #00bfff80 !important;
    }


    .progress-bar__fg:hover {

        background:
            #35d9ff !important;

        box-shadow:
            0 0 12px #00d9ffcc !important;
    }


    /* Progress slider */

    .progress-bar__slider {

        background:
            #dcecff !important;

        box-shadow:
            0 0 8px #00c8ff99 !important;
    }


    .progress-bar__slider:hover {

        background:
            #ffffff !important;

        box-shadow:
            0 0 12px #00d9ff !important;
    }


    /* =========================
       MAIN SPOTIFY BACKGROUND
       ========================= */

    ._5658c6accf868644593ce36887a475b1-scss {

        background:
            transparent !important;
    }


    /* =========================
       MAIN CONTENT + WALLPAPER
       ========================= */

    .main-view-container__scroll-node {

        background-image:
            linear-gradient(
                #00152c88,
                #00000066
            ),
            url(https://www.image2url.com/r2/default/images/1788350372875-3ab4087f-9b76-488a-8e51-783d3f4f984f.jpeg) !important;

        background-size:
            cover !important;

        background-position:
            center !important;

        background-attachment:
            fixed !important;

        background-repeat:
            no-repeat !important;
    }


    /* =========================
       MAIN CONTENT OVERLAY
       ========================= */

    .main-view-container__scroll-node-child {

        background:
            #0000008c !important;

        width:
            100% !important;
    }


    /* =========================
       TRACK / SONG NAMES
       ========================= */

    .tracklist-name {

        color:
            #f1f5fa !important;

        font-weight:
            bold !important;

        text-shadow:
            0 0 5px #000000aa !important;
    }


    /* =========================
       TRACK ARTIST / SUBTEXT
       ========================= */

    .tracklist-row__artist-name {

        color:
            #aebdca !important;
    }


    /* =========================
       TRACK ROWS
       ========================= */

    .tracklist-row {

        border-radius:
            4px !important;

        transition:
            background 0.15s ease,
            box-shadow 0.15s ease !important;
    }


    /* Track hover */

    .tracklist-row:hover {

        background:
            #008cff30 !important;

        color:
            #ffffff !important;

        box-shadow:
            inset 2px 0 0 #00c8ff !important;
    }


    /* =========================
       HIGHLIGHTED TRACK
       ========================= */

    .tracklist-row.tracklist-row--highlighted {

        background:
            #00bfff45 !important;

        color:
            #ffffff !important;

        box-shadow:
            inset 3px 0 0 #00d9ff,
            0 0 12px #00aaff18 !important;
    }


    .tracklist-row.tracklist-row--highlighted:hover {

        background:
            #008cff55 !important;

        color:
            #ffffff !important;
    }


    /* =========================
       CONTEXT MENU HOVER
       ========================= */

    .react-contextmenu-wrapper:hover {

        background:
            #00aaff12 !important;
    }


    /* =========================
       BUTTONS
       ========================= */

    button:hover {

        color:
            #00cfff !important;

        filter:
            drop-shadow(
                0 0 5px #00cfff66
            ) !important;
    }


    /* =========================
       SPOTIFY PLAY BUTTON
       ========================= */

    .control-button--circled {

        color:
            #e9f5ff !important;
    }


    .control-button--circled:hover {

        color:
            #00d9ff !important;

        filter:
            drop-shadow(
                0 0 8px #00d9ff99
            ) !important;
    }


    /* =========================
       SEARCH BAR
       ========================= */

    .search-input {

        background:
            #050a10cc !important;

        color:
            #edf7ff !important;

        border:
            1px solid #00bfff35 !important;
    }


    .search-input:focus {

        border-color:
            #00cfff !important;

        box-shadow:
            0 0 12px #00bfff30 !important;
    }


    /* =========================
       TEXT
       ========================= */

    .main-type-canon {

        color:
            #edf3f8 !important;
    }


    /* =========================
       LINKS
       ========================= */

    a:hover {

        color:
            #00d9ff !important;

        text-shadow:
            0 0 6px #00cfff55 !important;
    }


    /* =========================
       SCROLLBAR
       ========================= */

    ::-webkit-scrollbar {

        width:
            8px !important;
    }


    ::-webkit-scrollbar-track {

        background:
            #00000066 !important;
    }


    ::-webkit-scrollbar-thumb {

        background:
            #008fc455 !important;

        border-radius:
            10px !important;
    }


    ::-webkit-scrollbar-thumb:hover {

        background:
            #00cfffaa !important;

        box-shadow:
            0 0 8px #00cfff66 !important;
    }


    /* =========================
       TEXT SELECTION
       ========================= */

    ::selection {

        background:
            #00bfff66 !important;

        color:
            #ffffff !important;
    }
}
